+	}
+	dec := json.NewDecoder(bytes.NewReader(raw))
+	if _, err := dec.Token(); err != nil {
+		return err
+	}
+	for dec.More() {
+		token, err := dec.Token()
+		if err != nil {
+			return err
+		}
+		key := token.(string)
+		child, ok := fields[key]
+		if !ok {
+			return fmt.Errorf("json: unknown field %q", key)
+		}
+		var value json.RawMessage
+		if err := dec.Decode(&value); err != nil {
+			return err
+		}
+		if child != nil {
+			if err := rejectInexactTaskFields(value, child); err != nil {
+				return err
+			}
+		}
+	}
+	return nil
 }

